import React, { useState } from 'react';
import {
  JxCard,
  JxFormField,
  JxInput,
  JxSelect,
  JxSelectOption,
  JxSwitch,
  JxButton,
  JxAlert,
  JxStack,
} from '@jinx-ui/react';

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const ROLE_OPTIONS = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const TeamInviteForm: React.FC = () => {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const isEmailValid = EMAIL_REGEX.test(email);
  const showError = touched && email.length > 0 && !isEmailValid;
  const canSubmit = isEmailValid;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!canSubmit) return;
    setSubmitted(true);
  };

  return (
    <JxStack direction="column" gap="var(--jx-space-4)" style={{ maxWidth: 420 }}>
      {submitted && (
        <JxAlert
          variant="success"
          onClose={() => setSubmitted(false)}
        >
          Приглашение отправлено на {email}
        </JxAlert>
      )}

      <JxCard padding="var(--jx-space-5)">
        <form onSubmit={handleSubmit}>
          <JxStack direction="column" gap="var(--jx-space-4)">
            <JxFormField
              label="Email"
              hint="Мы отправим приглашение на этот адрес"
              error={showError ? 'Введите корректный email-адрес' : undefined}
            >
              <JxInput
                type="email"
                value={email}
                placeholder="name@company.com"
                invalid={showError}
                onChange={(e: React.ChangeEvent<HTMLInputElement>) => setEmail(e.target.value)}
                onBlur={() => setTouched(true)}
              />
            </JxFormField>

            <JxFormField label="Роль">
              <JxSelect
                value={role}
                onChange={(value: string) => setRole(value)}
              >
                {ROLE_OPTIONS.map((option) => (
                  <JxSelectOption key={option.value} value={option.value}>
                    {option.label}
                  </JxSelectOption>
                ))}
              </JxSelect>
            </JxFormField>

            <JxSwitch
              checked={notify}
              onChange={(checked: boolean) => setNotify(checked)}
              label="Отправить уведомление на почту"
            />

            <JxButton type="submit" variant="primary" disabled={!canSubmit}>
              Отправить приглашение
            </JxButton>
          </JxStack>
        </form>
      </JxCard>
    </JxStack>
  );
};

export default TeamInviteForm;

